#!/bin/bash
# 台の高さごとの縦の速さと足を上げる量（jb72、§35）: base_bh に JUMP_BOX_V・JUMP_BOX_TUCK を振る。12.5 cm: 3.0/0.125（足だけ上げる）、3.2/0.125、3.3/0.125。15 cm: 3.5/0.10（速さだけ）、3.0/0.15（足だけ）、3.75/0.15。種 27182 N=16 と種 16180 N=8。比べる相手は jb71 の BH・V35。
D=/home/takara/work/dp/articara/log/claude_g1jump_20261021; B=$D/g1_flight_probe_base_bh
X='"JUMP_ABORT":"1","JUMP_PUSH_R":"0.3","QD_CLAMP":"40","DIAG_TD":"1","FLIGHT_FEET_FLAT":"1","DIAG_HX":"1","RELEASE_FIRST_OFF":"1","WBCW_CONTACT_REST":"0.1","WBCW_TRUNK_LAND":"0.03","FALL_TILT":"1.5","LAND_REF_FOLLOW":"2","AIR_ABORT_T":"0.08"'
H=',"FLIGHT_FEET_CAPTURE_T":"0.06","KP_FLIGHT_FEET":"1000","KD_FLIGHT_FEET":"63","WBCW_TRUNK_PUSH":"0.003","WBCW_MOMENTUM":"10","WBCW_CONTACT":"100","WBCW_TRUNK_LAND_VZ":"0","JUMP_H_NAT":"1","WBCW_CONTACT_REST_LAUNCH":"1","FLIGHT_FEET_CAPTURE":"0.55","FLIGHT_TRUNK":"0","FLIGHT_FEET_W":"10","WBCW_MOMENTUM_PUSH":"1","MU_TORSION":"0.02","TRUNK_RP_YAWED":"1"'
TB=',"JUMP_VX_TAB":"1.0:1.0,1.5:1.2,2.0:1.6","JUMP_LEAN_TAB":"1.0:0,1.5:0.045,2.0:0.06"'
R=',"JUMP_REPEAT":"5","JUMP_REPEAT_RECENTRE":"1","JUMP_REPEAT_SOFT_CROUCH":"1","FLIGHT_FEET_WIDTH":"0.236","WBCW_TRUNK_LAND_T":"1.0","T":"24","FLIGHT_FEET_YAW":"1"'
FT='1.5|0:-0.112,0.25:-0.026,0.4:0.021,0.5:0.068,0.55:0.090,0.6:0.124,0.65:0.230,0.7:0.265,0.85:0.290,1.0:0.334,1.1:0.347;2.0|0:-0.148,0.25:-0.026,0.4:0.038,0.5:0.104,0.55:0.131,0.6:0.161,0.65:0.216,0.7:0.249,0.75:0.271,0.85:0.325,1.0:0.362'
cd $D
cd $D
M='"JUMP_BOX_GAP":"0.10","JUMP_BOX_GAP_TOL":"0.025","JUMP_BOX_S":"1.2","JUMP_BOX_CROUCH_W":"1","JUMP_BOX_V_TABS":"1","LAND_REF_SOLES":"0.5","KP_TRUNK_LAND_BOX":"60","KD_TRUNK_LAND_BOX":"60"'
bh() { # TAG BOX_H SEED N JUMP_BOX_V TUCK
  for b in 20 30 40 60; do
    (TAG=$1_$b SEED=$3 BIN=$B CONDS=1.5,2.0 N=$4 W=1 EXTRA="{$X$H$TB$R,\"JUMP_FWD_TAB\":\"$FT\",\"JUMP_BOX_TUCK\":\"$6\",\"JUMP_BOX\":\"0.$b,$2\",$M,\"JUMP_BOX_V\":\"$5\"}" python3 jrand.py) &
  done
}
# TAG = V<速さ>T<足>{s,h}<高さ>
bh V30T125s125 0.125 27182 16 3.0 0.125; bh V32T125s125 0.125 27182 16 3.2 0.125; bh V33T125s125 0.125 27182 16 3.3 0.125; bh V35T10s15 0.15 27182 16 3.5 0.10
wait
bh V375T15s15 0.15 27182 16 3.75 0.15; bh V30T15s15 0.15 27182 16 3.0 0.15; bh V30T125h125 0.125 16180 8 3.0 0.125; bh V32T125h125 0.125 16180 8 3.2 0.125
wait
bh V33T125h125 0.125 16180 8 3.3 0.125; bh V35T10h15 0.15 16180 8 3.5 0.10; bh V375T15h15 0.15 16180 8 3.75 0.15; bh V30T15h15 0.15 16180 8 3.0 0.15
wait
for p in V30T125s125 V32T125s125 V33T125s125 V35T10s15 V375T15s15 V30T15s15 V30T125h125 V32T125h125 V33T125h125 V35T10h15 V375T15h15 V30T15h15; do python3 jbsumm.py ${p}_20 ${p}_30 ${p}_40 ${p}_60; done
for s in s h; do for c in V30T125 V32T125 V33T125; do python3 pairchurn.py BH${s}125 ${c}${s}125; done; for c in V35T10 V375T15 V30T15; do python3 pairchurn.py BH${s}15 ${c}${s}15; done; python3 pairchurn.py V35${s}15 V375T15${s}15; done
echo "#### JB72_DONE"
